<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch} from 'vue'
import {Upload,Pause,Play,Check,FileText,X} from 'lucide-vue-next'
import Sheet from '../components/Sheet.vue'
import {useLocal} from '../stores/local'
import {importManifest,importEntries,stageImportFile,convertImportEntry,updateImportEntry,recordImportStageError} from './import-queue'
import type {ImportEntry} from './import-contract'
import type {ImportEncoding,ImportProgress} from '../repositories/local-import'
import type {Document} from '../domain/local-contract'
import type {WriteDocument} from '../repositories/local-vault'
const emit=defineEmits<{close:[];committed:[]}>(),store=useLocal(),rows=ref<Document<ImportEntry>[]>([]),files=ref<File[]>([]),encoding=ref<ImportEncoding>('auto'),busy=ref(false),error=ref(''),progress=ref<ImportProgress|null>(null),current=ref(''),dragging=ref(false)
let disposed=false,loadEpoch=0,controller:AbortController|null=null,intent:{id:string;files:File[];writes:WriteDocument[]}|null=null
const statuses={needs_file:'需要原文件',ready:'待转换',importing:'转换中',failed:'未完成',cancelled:'已停止',complete:'已入库',rejected:'不支持'}
function fileSize(bytes:number){return bytes<1024?bytes+' B':bytes<1024*1024?(bytes/1024).toFixed(1)+' KiB':(bytes/(1024*1024)).toFixed(1)+' MiB'}
async function load(){const vault=store.vault;if(!vault)return;const ticket=++loadEpoch;try{const loaded=await importEntries(vault);if(!disposed&&store.vault===vault&&ticket===loadEpoch)rows.value=loaded.filter(row=>!row.value.retired)}catch(e){if(!disposed&&store.vault===vault&&ticket===loadEpoch)error.value=(e as Error).message}}
function selected(event:Event){files.value=Array.from((event.target as HTMLInputElement).files||[]);intent=null;error.value='';(event.target as HTMLInputElement).value=''}
function dropped(event:DragEvent){dragging.value=false;if(busy.value)return;files.value=Array.from(event.dataTransfer?.files||[]);intent=null;error.value=files.value.length?'':'请选择文件，或使用目录选择'}
async function start(defer=false){const vault=store.vault;if(!vault||busy.value||!files.value.length)return;busy.value=true;error.value='';controller=new AbortController();try{
 if(!intent)intent={id:crypto.randomUUID(),files:[...files.value],writes:importManifest(files.value,encoding.value)}
 const currentIntent=intent;await vault.commitBundle(currentIntent.id,currentIntent.writes,controller.signal);await load()
 for(let i=0;i<currentIntent.files.length;i++){controller.signal.throwIfAborted();current.value=currentIntent.files[i]!.name;try{await stageImportFile(vault,currentIntent.writes[i]!.id,currentIntent.files[i]!,controller.signal)}catch(e){if((e as Error).name==='AbortError'||!vault.unlocked)throw e;await recordImportStageError(vault,currentIntent.writes[i]!.id,(e as Error).message)}await load()}
 if(!defer)for(const row of rows.value.filter(row=>currentIntent.writes.some(w=>w.id===row.id)&&['ready','failed','cancelled'].includes(row.value.status))){controller.signal.throwIfAborted();await convert(row,false,controller.signal)}
 files.value=[];intent=null
 }catch(e){if(!disposed&&store.vault===vault)error.value=(e as Error).name==='AbortError'?'导入已停止':(e as Error).message}finally{if(!disposed&&store.vault===vault){busy.value=false;current.value='';progress.value=null;await load()}controller=null}}
async function convert(row:Document<ImportEntry>,takeover:boolean,signal:AbortSignal){const vault=store.vault;if(!vault)return;current.value=row.value.name;try{await convertImportEntry(vault,row.id,signal,p=>{if(!disposed&&store.vault===vault)progress.value=p},takeover);if(!disposed&&store.vault===vault)emit('committed')}catch(e){if((e as Error).name==='AbortError'||!vault.unlocked)throw e;if(!disposed&&store.vault===vault)error.value=(e as Error).message}finally{if(!disposed&&store.vault===vault)await load()}}
async function resume(row:Document<ImportEntry>){if(busy.value||!store.vault)return;busy.value=true;error.value='';controller=new AbortController();try{await convert(row,row.value.status==='importing',controller.signal)}catch(e){if(!disposed)error.value=(e as Error).name==='AbortError'?'导入已停止':(e as Error).message}finally{if(!disposed){busy.value=false;current.value='';progress.value=null}controller=null}}
async function reselect(row:Document<ImportEntry>,event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0],vault=store.vault;input.value='';if(!file||!vault||busy.value)return;busy.value=true;controller=new AbortController();try{await stageImportFile(vault,row.id,file,controller.signal);if(!disposed&&store.vault===vault)await load()}catch(e){if(!disposed&&store.vault===vault)error.value=(e as Error).message}finally{if(!disposed&&store.vault===vault)busy.value=false;controller=null}}
async function change(row:Document<ImportEntry>,event:Event){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{await updateImportEntry(vault,row.id,{encoding:(event.target as HTMLSelectElement).value as ImportEncoding});if(!disposed&&store.vault===vault)await load()}catch(e){if(!disposed&&store.vault===vault)error.value=(e as Error).message}finally{if(!disposed&&store.vault===vault)busy.value=false}}
async function retire(row:Document<ImportEntry>){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{await updateImportEntry(vault,row.id,{retired:true});if(!disposed&&store.vault===vault)await load()}catch(e){if(!disposed&&store.vault===vault)error.value=(e as Error).message}finally{if(!disposed&&store.vault===vault)busy.value=false}}
function committed(event:Event){const d=(event as CustomEvent<{vaultId:string;ids:string[]}>).detail;if(d?.vaultId===store.vault?.id&&d.ids.some(id=>id.startsWith('import-entry:')))void load()}
function lock(){controller?.abort();emit('close')}
watch(()=>store.vault,()=>{controller?.abort();rows.value=[];files.value=[];intent=null;emit('close')})
onMounted(()=>{void load();window.addEventListener('reader-private-commit',committed);window.addEventListener('reader-local-locked',lock)})
onUnmounted(()=>{disposed=true;controller?.abort();files.value=[];intent=null;window.removeEventListener('reader-private-commit',committed);window.removeEventListener('reader-local-locked',lock)})
</script>
<template><Sheet title="导入中转站" @close="emit('close')"><div class="import-queue"><form class="queue-drop" :class="{dragging}" @dragover.prevent="dragging=!busy" @dragleave="dragging=false" @drop.prevent="dropped" @submit.prevent="start()"><label>TXT / Markdown / EPUB<input type="file" accept=".txt,.md,.markdown,.epub" multiple :disabled="busy" @change="selected"></label><label class="queue-directory">选择目录<input type="file" webkitdirectory multiple :disabled="busy" aria-label="选择目录" @change="selected"></label><label>文件编码<select v-model="encoding" :disabled="busy" aria-label="文件编码"><option value="auto">自动识别</option><option value="utf-8">UTF-8</option><option value="utf-16le">UTF-16 LE</option><option value="utf-16be">UTF-16 BE</option><option value="gb18030">GB18030 / GBK</option><option value="big5">Big5</option></select></label><p v-if="files.length" class="queue-picked" role="status">已选择 {{files.length}} 个文件</p><div class="queue-actions"><button class="final-primary" :disabled="busy||!files.length"><Upload :size="17"/>导入 {{files.length}} 个文件</button><button type="button" :disabled="busy||!files.length" @click="start(true)">保存，稍后转换</button><button v-if="busy" type="button" @click="controller?.abort()"><Pause :size="17"/>停止</button></div></form><p v-if="error" class="final-error" role="alert">{{error}}</p><p v-if="busy&&current" role="status">{{current}}<small v-if="progress"> · {{progress.chapters}} 章</small></p><ul aria-label="导入记录"><li v-for="row in rows" :key="row.id"><div class="queue-file"><Check v-if="row.value.status==='complete'" :size="20"/><FileText v-else :size="20"/><div><strong>{{row.value.name}}</strong><small>{{statuses[row.value.status]}} · {{fileSize(row.value.bytes)}}</small></div><button :aria-label="'移出记录 '+row.value.name" :disabled="busy" @click="retire(row)"><X :size="17"/></button></div><p v-if="row.value.error" class="queue-error">{{row.value.error}}</p><div v-if="!['complete','rejected'].includes(row.value.status)" class="queue-row-actions"><label v-if="row.value.status==='needs_file'">重新选择原文件<input type="file" :disabled="busy" @change="reselect(row,$event)"></label><template v-else><select :value="row.value.encoding" :aria-label="'编码 '+row.value.name" :disabled="busy||row.value.status==='importing'" @change="change(row,$event)"><option value="auto">自动识别</option><option value="utf-8">UTF-8</option><option value="utf-16le">UTF-16 LE</option><option value="utf-16be">UTF-16 BE</option><option value="gb18030">GB18030 / GBK</option><option value="big5">Big5</option></select><button :aria-label="'继续 '+row.value.name" :disabled="busy" @click="resume(row)"><Play :size="16"/>{{row.value.status==='importing'?'接管并继续':'转换'}}</button></template></div><RouterLink v-if="row.value.storyId" class="final-text-link" :to="'/local/read/'+row.value.storyId">打开书籍</RouterLink></li></ul><p v-if="!rows.length&&!busy" class="final-subtle">还没有导入记录</p></div></Sheet></template>
<style scoped>.queue-drop{border:1px dashed var(--edge);border-radius:18px;padding:20px;transition:background .15s,border-color .15s}.queue-drop.dragging{background:var(--wash);border-color:var(--accent)}.queue-picked{margin:0;color:var(--muted);font-size:13px}.queue-directory{font-size:13px;color:var(--muted)}.import-queue,.import-queue form{display:grid;gap:20px}.import-queue input,.import-queue select{width:100%;min-height:44px}.queue-actions,.queue-row-actions{display:flex;gap:12px;flex-wrap:wrap}.queue-row-actions>*{flex:1;min-width:140px}.import-queue button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px}.import-queue ul{list-style:none;padding:0;margin:0}.import-queue li{padding:24px 0;border-top:1px solid var(--edge);display:grid;gap:16px}.queue-file{display:flex;align-items:center;gap:14px}.queue-file>div{display:grid;gap:6px;flex:1;min-width:0}.queue-file strong{overflow-wrap:anywhere;font-weight:500}.queue-file small{color:var(--muted)}.queue-file button{flex:0 0 44px;width:44px;padding:0}.queue-error{color:var(--muted);overflow-wrap:anywhere}.import-queue p[role=status]{overflow-wrap:anywhere}</style>
